mapper.update:
UPDATE `iot_device_fault` SET is_deleted = 1, status = 3 WHERE id IN
#{id}
AND is_deleted = 0

UPDATE `iot_device_fault` SET status = #{status}
, handle_time = COALESCE(handle_time, NOW()), end_time = NOW(), duration = TIMESTAMPDIFF(MINUTE, start_time, NOW())
, handle_result = #{handleResult}
WHERE id = #{id} AND is_deleted = 0

UPDATE `iot_device_fault`
SET completion_image_url = #{imageUrl}
WHERE id = #{id} AND status = 2 AND is_deleted = 0

UPDATE `iot_device_fault`
SET assign_status = #{assignStatus},
    status = #{status}


    , handle_time = COALESCE(handle_time, NOW())


    , handle_result = #{handleResult}

WHERE id = #{id} AND is_deleted = 0

mapper.select:
SELECT COUNT(1)
FROM `iot_device_fault` f
JOIN `iot_device` d ON d.id = f.device_id
WHERE f.id = #{id}
  AND d.user_id = #{userId}
  AND f.is_deleted = 0

SELECT 
FROM `iot_device_fault` f


    AND f.is_deleted = 0

        AND d.user_id = #{userId}


        AND f.device_id = #{deviceId}


        AND d.name LIKE CONCAT('%', #{deviceName}, '%')


        AND f.fault_code LIKE CONCAT('%', #{faultCode}, '%')


        AND f.fault_name LIKE CONCAT('%', #{faultName}, '%')


        AND f.fault_type = #{faultType}


        AND f.severity = #{severity}


        AND f.status = #{status}


        AND f.handle_user_id = #{handleUserId}


ORDER BY f.status ASC, f.severity DESC, f.start_time DESC, f.id DESC
